content.query:
let fallos = Event | where Source == "AndinaSonda" and EventID == 2001 | project t = TimeGenerated
| order by t asc | extend nuevo = iff(isnull(prev(t)) or t - prev(t) > 5m, 1, 0) | extend incidente = row_cumsum(nuevo);
let rangos = fallos | summarize inicio = min(t), ultimo_fallo = max(t) by incidente;
let rem = Event | where Source == "AndinaRemediacion" and EventID in (3000, 3001, 3002, 3003)
| extend d = parse_json(RenderedDescription) | project tr = TimeGenerated, EventID, disparo = todatetime(d.disparo), resultado = tostring(d.resultado), k = 1;
rangos | extend k = 1
| join kind=leftouter rem on k
| where isnull(tr) or (tr between (inicio .. ultimo_fallo + 10m))
| summarize detectado = min(disparo), resultado = take_any(resultado) by incidente, inicio, ultimo_fallo
| extend Duracion_min = round((ultimo_fallo - inicio) / 1m + 0.33, 1), MTTD_min = round((detectado - inicio) / 1m, 1),
         Como_se_resolvio = case(resultado == "Recuperado", "Automático", isempty(resultado), "Sin remediación", "Escalado a una persona")
| project Inicio = inicio, Duracion_min, MTTD_min, Como_se_resolvio
| order by Inicio desc
